 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);g=b.new_page(viewport={'width':1024,'height':768},has_touch=True);g.set_default_timeout(120000);g.goto('http://127.0.0.1:5175/adventures.html?test=1');g.wait_for_function('window.adventure?.ready');g.locator('#enter').click();g.evaluate('window.requestAnimationFrame=()=>0');g.wait_for_timeout(100)
 r=g.evaluate('''()=>{const g=adventure.game,root=g.landscape.group.children.find(c=>c.userData.bridge),box=g.selectionOutline.box.clone().setFromObject(root),samples=[],bx=root.position.x;root.updateMatrixWorld(true);for(const z of[-53,-52,-51])for(let dx=-5;dx<=5;dx+=.25){const x=bx+dx,ys=[];root.traverse(o=>{if(!o.isMesh)return;const a=o.geometry.getAttribute('position'),ix=o.geometry.index,vs=[0,1,2].map(()=>g.camera.position.clone());for(let i=0;i<(ix?.count??a.count);i+=3){for(let j=0;j<3;j++)vs[j].fromBufferAttribute(a,ix?ix.getX(i+j):i+j).applyMatrix4(o.matrixWorld);const[A,B,C]=vs,d=(B.z-C.z)*(A.x-C.x)+(C.x-B.x)*(A.z-C.z);if(Math.abs(d)<1e-8)continue;const u=((B.z-C.z)*(x-C.x)+(C.x-B.x)*(z-C.z))/d,v=((C.z-A.z)*(x-C.x)+(A.x-C.x)*(z-C.z))/d,w=1-u-v;if(Math.min(u,v,w)>-.0001)ys.push(A.y*u+B.y*v+C.y*w);}});Object.assign(g.player,{x,y:0,z});g.velocity.set(0,0);g.debugCamera=false;g.update(1/120,{x:0,z:0,run:false});samples.push({dx,x,z,walkY:g.player.y,ys:ys.sort((a,b)=>b-a)});}g.debugCamera=false;Object.assign(g.player,{x:bx+4.5,z:-52,y:0});g.cameraYaw=2;g.cameraPitch=.6;g.cameraPosition.set(0,0,0);g.cameraUpdate(1/60);g.renderScene();document.getElementById('toast').hidden=true;return{box,position:root.position,scale:root.scale,fit:root.userData.bridge,samples}}''');r['checks']=[{'name':'aligned deck exists across the whole actual walking corridor','passed':all(row['ys'] for row in r['samples'] if abs(row['dx'])<=4.5)},{'name':'walking surface matches actual indexed bridge deck with small foot clearance','passed':all(.001<row['walkY']-row['ys'][0]<.035 for row in r['samples'] if abs(row['dx'])<=4.5)}];(OUT/'bridge-surface-aligned.json').write_text(json.dumps(r,indent=2)+'\n');g.screenshot(path=str(OUT/'screenshots'/'bridge-aligned-initial.png'));print(json.dumps({'fit':r['fit'],'profile':[(p['dx'],p['ys'])for p in r['samples']if p['z']==-52]},indent=2),flush=True);assert all(row['passed']for row in r['checks']);b.close()
